 const tick=Number(check({type:'game-tick'})||0),now=Number(X.clock?.absoluteMinutes||0),W=X.work??(X.work={queue:[],results:{},history:[]}),domains=C.domains||{},num=x=>Number.isFinite(Number(x))?Number(x):0;
