m.revision++;
}
}
}}

lcx_shared_setup.script:
// WORLD-MAKER CONFIGURATION. Change only the declaration object below.
// Bank/account, inventory, research/project, meter, tracker. All state is held in existing LCX domains.
const LCX_AUTHOR_TRUSTED_ADAPTERS = {
  // "verified-native-bank": true // Only name a host trigger that supplies confirmed authoritative receipts.
};
const LCX_AUTHOR_SHARED = {
  // "Expedition Fund": "bank",
  // "Engine Research": {type:"research", target:100, requires:["prototype_test"]},
  // "Party Supplies": "inventory",
  // "Ship Fuel": {type:"meter", max:500},
  // "Settlement": {type:"tracker", fields:{houses:"number", evacuated:"flag", phase:["planning","building","complete"]}}
};
{
const X=storage.LCX;
if(!X){skip=true;}else{
 const obj=v=>v&&typeof v==='object'&&!Array.isArray(v), safe=k=>typeof k==='string'&&/^[a-zA-Z0-9_:.-]{1,90}$/.test(k)&&!['__proto__','constructor','prototype'].includes(k),clean=s=>String(s||'').toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,64),O=X.sharedCoord??(X.sharedCoord={defs:{},pending:{},history:[],lastSeq:{},diagnostics:[],seen:{}}),R=X.registries;
 R.trackers=R.trackers||{};O.defs=O.defs||{};O.pending=O.pending||{};O.history=Array.isArray(O.history)?O.history:[];O.lastSeq=O.lastSeq||{};O.diagnostics=[];O.seen=O.seen||{};
 X.config=X.config||{};X.config.modules=X.config.modules||{};if(X.config.modules.sharedCoord===undefined)X.config.modules.sharedCoord=true;
 X.config.sharedCoord=X.config.sharedCoord||{trustedAdapters:{},maxOps:24,maxHistory:120,maxContextChars:600,maxDefinitions:96};
 if(X.config.modules.sharedCoord===false){skip=true;}else{
 const C=X.config.sharedCoord;C.trustedAdapters=C.trustedAdapters||{};for(const aid of O.authorAdapters||[])if(!Object.prototype.hasOwnProperty.call(LCX_AUTHOR_TRUSTED_ADAPTERS,aid))delete C.trustedAdapters[aid];O.authorAdapters=[];for(const [aid,on] of Object.entries(LCX_AUTHOR_TRUSTED_ADAPTERS)){if(safe(aid)&&on===true){C.trustedAdapters[aid]=true;O.authorAdapters.push(aid);}}const putDiag=(id,msg)=>{if(O.diagnostics.length<24)O.diagnostics.push({id,message:msg});};
 const specs=Object.entries(LCX_AUTHOR_SHARED);if(specs.length>Math.min(96,Math.max(1,Number(C.maxDefinitions)||96)))putDiag('definitions','too-many');
 for(const [label,raw] of specs.slice(0,Math.min(96,Math.max(1,Number(C.maxDefinitions)||96)))){
  if(typeof raw!=='string'&&!obj(raw)){putDiag(label,'definition-must-be-preset-or-object');continue;}
  const d=typeof raw==='string'?{type:raw}:raw,type=String(d.type||'').toLowerCase(),k=({account:'bank',wallet:'bank',supplies:'inventory',stock:'inventory',project:'research',construction:'research'}[type]||type),id=String(d.id||clean(label));
  if(!safe(id)||!['bank','inventory','research','meter','tracker'].includes(k)){putDiag(label,'invalid-id-or-type');continue;}
  const owner=String(d.owner||'party'),scope=String(d.scope||'party'),visibility=String(d.visibility||'members'),access=String(d.access|| (['party','group'].includes(scope)?'members':'owner'));
  if(!['party','player','faction','organization','location','entity','world','group'].includes(scope)||!['public','members','private'].includes(visibility)||!['members','owner','writers'].includes(access)){putDiag(label,'invalid-scope-or-visibility');continue;}
  if(scope!=='party'&&!d.owner){putDiag(label,'nonparty-requires-owner');continue;}
  let valid=true,fields={};if(k==='tracker'){
    for(const [f,t] of Object.entries(obj(d.fields)?d.fields:{})){
     if(!safe(f)||!(t==='number'||t==='flag'||t==='text'||Array.isArray(t)&&t.length>0&&t.length<33&&t.every(x=>typeof x==='string'&&x.length<80))){valid=false;break;}fields[f]=t;
    }
  }
  const target=Number(d.target??d.goal??100),min=Number(d.min??0),max=d.max===undefined?null:Number(d.max);
  if(!valid||k==='research'&&(!Number.isSafeInteger(target)||target<1)||k==='meter'&&(!Number.isFinite(min)||max!==null&&(!Number.isFinite(max)||max<min))){putDiag(id,'invalid-field-schema-or-bounds');continue;}
  const def={id,label:String(label).slice(0,120),kind:k,scope,owner,visibility,access,members:Array.isArray(d.members)?d.members.map(String).filter(safe).slice(0,64):[],writers:Array.isArray(d.writers)?d.writers.map(String).filter(safe).slice(0,64):[],requires:Array.isArray(d.requires)?d.requires.map(String).slice(0,24):[],target:k==='research'?target:null,min:k==='meter'?min:null,max:k==='meter'?max:null,fields,description:String(d.description||'').slice(0,300)};
  const seed=d.start;
  if(seed!==undefined){
   const validItem=(name,v)=>safe(name)&&Number.isSafeInteger(v)&&v>=0&&v<=1000000000000;
   if(k==='bank'||k==='inventory'){
    if(!obj(seed)||Object.keys(seed).length>64||!Object.entries(seed).every(([name,v])=>validItem(name,v)))valid=false;
   }else if(k==='meter')valid=typeof seed==='number'&&Number.isSafeInteger(seed)&&seed>=min&&(max===null||seed<=max);
   else if(k==='tracker')valid=obj(seed)&&Object.entries(seed).every(([f,v])=>Object.prototype.hasOwnProperty.call(fields,f)&&(fields[f]==='number'?Number.isSafeInteger(v):fields[f]==='flag'?typeof v==='boolean':fields[f]==='text'?typeof v==='string'&&v.length<=500:Array.isArray(fields[f])&&fields[f].includes(v)));
   else valid=false; // research starts at zero; evidence must establish progress
   if(!valid){putDiag(id,'invalid-starting-allocation');continue;}
   def.seed=seed; // world-maker declaration metadata only, not a second balance
  }
  const old=O.defs[id];if(old){if(JSON.stringify(old)!==JSON.stringify(def))putDiag(id,'definition-changed: existing state retained; review migration');continue;}
  let collision=false;for(const [other,oldDef] of Object.entries(O.defs))if(other!==id&&oldDef.label===def.label)collision=true;
  if(collision){putDiag(id,'duplicate-label');continue;}
  if(k==='bank'&&Object.prototype.hasOwnProperty.call(R.economy,id)&&R.economy[id]._lcxShared!==true||k==='research'&&Object.prototype.hasOwnProperty.call(R.projects,id)&&R.projects[id]._lcxShared!==true||k==='meter'&&Object.prototype.hasOwnProperty.call(R.accumulators,id)&&R.accumulators[id]._lcxShared!==true||k==='tracker'&&Object.prototype.hasOwnProperty.call(R.trackers,id)&&R.trackers[id]._lcxShared!==true){putDiag(id,'domain-id-collision');continue;}
  if(k==='inventory'&&obj(seed)&&Object.keys(seed).some(item=>Object.prototype.hasOwnProperty.call(X.physical?.batches||{},'shared:'+id+':'+item))){putDiag(id,'seed-collides-with-existing-physical-batch');continue;}
  O.defs[id]=def;
  if(k==='bank')R.economy[id]={id,kind:'shared-account',label:def.label,balances:k==='bank'&&obj(seed)?Object.assign({},seed):{},_lcxShared:true,revision:0};
  if(k==='research')R.projects[id]={id,label:def.label,kind:'shared-project',sharedManaged:true,enabled:true,autonomous:false,progress:0,progressUnits:0,requiredUnits:target,status:'active',blockers:def.requires.slice(),contributions:{},evidence:[],_lcxShared:true,revision:0};
  if(k==='meter')R.accumulators[id]={id,label:def.label,value:k==='meter'&&typeof seed==='number'?seed:min,min,max,ratePerMinute:0,enabled:true,_lcxShared:true,revision:0};
  if(k==='tracker')R.trackers[id]={id,label:def.label,values:Object.assign(Object.fromEntries(Object.entries(fields).map(([f,t])=>[f,t==='number'?0:t==='flag'?false:Array.isArray(t)?t[0]:''])),obj(seed)?seed:{}),_lcxShared:true,revision:0};
  if(k==='inventory'&&obj(seed)){for(const [item,quantity] of Object.entries(seed)){const batchId='shared:'+id+':'+item;if(X.physical?.batches?.[batchId]){putDiag(id,'physical-batch-already-exists:'+item);continue;}X.physical.batches[batchId]={batchId,kind:'shared-resource-batch',item,quantity,reserved:0,_lcxShared:true,ownerId:id,revision:0};}}
  // Inventory deliberately uses X.physical.batches as the single canonical quantity source; no shadow quantities.
 }
 for(const [id,d] of Object.entries(O.defs)){if(!specs.some(([label,raw])=>String((raw&&typeof raw==='object'?raw.id:null)||clean(label))===id))putDiag(id,'definition-removed-from-author-config: preserved pending explicit migration');}

 }
}
}

lcx_shared_commit.script:
{
const X=storage.LCX;if(!X||X.config?.modules?.sharedCoord===false){skip=true;}else{
 const S=X.sharedCoord;if(!S){skip=true;}else{
 const R=X.registries,now=Number(X.clock?.absoluteMinutes||0),tick=Number(check({type:'game-tick'})||0),C=X.config?.sharedCoord||{},L=S.history??(S.history=[]),last=S.lastSeq??(S.lastSeq={}),seen=S.seen??(S.seen={});
 const has=(o,k)=>Object.prototype.hasOwnProperty.call(o||{},k),str=x=>typeof x==='string'&&x.length>0&&x.length<100&&!['__proto__','constructor','prototype'].includes(x),num=x=>typeof x==='number'&&Number.isSafeInteger(x)&&Math.abs(x)<=1000000000000;
 const fail=(id,why)=>{L.push({id,tick,at:now,status:'rejected',reason:why});};
 const pending=S.pending??(S.pending={}),limit=Math.min(48,Math.max(1,Number(C.maxOps)||24)),list=Object.entries(pending).slice(0,limit);
 for(const [id,job] of list){delete pending[id];let why='',touched={},actor='',seq=0,adapter='',changes=[];
  const tx=id=>Object.prototype.hasOwnProperty.call(touched,id)?touched[id]:null;
  if(!str(id)||!job||typeof job!=='object'||Array.isArray(job)){fail(String(id),'invalid-envelope');continue;}
  adapter=String(job.adapter||'');actor=String(job.actor||'');seq=job.seq;changes=job.changes;
  if(!str(adapter)||!C.trustedAdapters||C.trustedAdapters[adapter]!==true)why='untrusted-adapter';
  else if(job.confirmed!==true||!str(String(job.receipt||'')))why='missing-confirmed-receipt';
  else if(!str(actor))why='invalid-actor';
  else if(!num(seq)||seq<=Number(last[adapter]||0))why='stale-adapter-sequence';
  else if(seen[id])why='duplicate-id';
  else if(!Array.isArray(changes)||changes.length<1||changes.length>24)why='invalid-changes';
  const players=Array.isArray(X.session?.players)?X.session.players.map(String):[];
  function allowed(d){if(d.writers.includes(actor))return true;if(d.scope==='party'&&players.includes(actor)&&d.access!=='owner')return true;if(d.scope==='group'&&d.access==='members'&&X.groups?.edges?.[d.owner+'|'+actor]?.active===true)return true;if(d.owner===actor&&['player','entity'].includes(d.scope))return true;return false;}
  function clone(o){return JSON.parse(JSON.stringify(o));}
  const scratch=new Map(),touch=(d,key,src)=>{if(!scratch.has(key))scratch.set(key,{d,value:clone(src)});return scratch.get(key).value;};
  const validField=(d,f,v)=>{const t=d.fields[f];return t==='number'?num(v):t==='flag'?typeof v==='boolean':t==='text'?typeof v==='string'&&v.length<=500:Array.isArray(t)?t.includes(v):false;};
  if(!why)for(const change of changes){
   if(!change||typeof change!=='object'){why='invalid-change';break;}
   const key=String(change.id||''),d=has(S.defs,key)?S.defs[key]:null,op=String(change.op||''),qty=change.amount;
   if(!d){why='unknown-resource';break;}if(!allowed(d)){why='permission-denied';break;}
   const dom=d.kind==='bank'?R.economy:d.kind==='research'?R.projects:d.kind==='meter'?R.accumulators:d.kind==='tracker'?R.trackers:null;
   const recId=d.kind==='inventory'?'shared:'+key+':'+String(change.item||''):key;
   if((!str(recId)&&!(d.kind==='inventory'&&recId.length<=230))||d.kind==='inventory'&&!str(change.item)){why='invalid-item';break;}
   const physical=d.kind==='inventory',src=physical?X.physical?.batches?.[recId]:dom?.[key];
   if(!src&&!physical||src&&src._lcxShared!==true){why='domain-missing-or-owned-by-another-system';break;}
   const start=src||(physical?{batchId:recId,kind:'shared-resource-batch',item:String(change.item),quantity:0,reserved:0,_lcxShared:true,ownerId:key,revision:0}:null);
   const obj=touch(d,recId,start);
   if(d.kind==='bank'){
    const cur=String(change.currency||'gold');if(!str(cur)||!num(qty)||qty<=0||!['credit','debit'].includes(op)){why='invalid-bank-operation';break;}
    obj.balances=obj.balances||{};const old=obj.balances[cur]||0;if(!num(old)){why='invalid-stored-balance';break;}const next=old+(op==='credit'?qty:-qty);if(!num(next)||next<0){why='insufficient-funds-or-overflow';break;}obj.balances[cur]=next;
   }else if(physical){
    if(!num(qty)||qty<=0||!['add','take','reserve','release','consume-reserved'].includes(op)){why='invalid-inventory-operation';break;}
    const q=Number(obj.quantity||0),r=Number(obj.reserved||0);if(!num(q)||!num(r)||q<0||r<0||r>q){why='invalid-stock';break;}
    if(op==='add')obj.quantity=q+qty;
    else if(op==='take'&&q-r>=qty)obj.quantity=q-qty;
    else if(op==='reserve'&&q-r>=qty)obj.reserved=r+qty;
    else if(op==='release'&&r>=qty)obj.reserved=r-qty;
    else if(op==='consume-reserved'&&r>=qty){obj.reserved=r-qty;obj.quantity=q-qty;}
    else{why='insufficient-available-inventory';break;}
    if(!num(obj.quantity)||!num(obj.reserved)){why='inventory-overflow';break;}
   }else if(d.kind==='meter'){
    if(op!=='adjust'||!num(qty)){why='invalid-meter-operation';break;}
    const next=Number(obj.value||0)+qty;if(!num(next)||next<d.min||d.max!==null&&next>d.max){why='meter-bounds';break;}obj.value=next;
   }else if(d.kind==='research'){
    if(op==='contribute'){
     if(!num(qty)||qty<=0||!change.evidence||change.evidence.verified!==true||!str(String(change.evidence.id||''))){why='unverified-project-contribution';break;}
     const evId=String(change.evidence.id);if((obj.evidence||[]).some(e=>e.id===evId)||obj.evidenceIndex?.[evId]){why='replayed-project-evidence';break;}
     if(obj.status==='completed'){why='project-completed';break;}
     const next=Number(obj.progressUnits||0)+qty,wm=Number(obj.workMinutes||0)+qty,con=Number(obj.contributions?.[actor]||0)+qty;if(!num(next)||!num(wm)||!num(con)){why='project-overflow';break;}
     obj.progressUnits=next;obj.progress=Math.min(1,next/d.target);obj.workMinutes=wm;obj.contributions=obj.contributions||{};obj.contributions[actor]=con;
     obj.evidence=obj.evidence||[];obj.evidence.push({id:evId,actor,amount:qty});obj.evidenceIndex=obj.evidenceIndex||{};obj.evidenceIndex[evId]=true;while(obj.evidence.length>120)obj.evidence.shift();const evKeys=Object.keys(obj.evidenceIndex);if(evKeys.length>256)for(const oldId of evKeys.slice(0,evKeys.length-256))delete obj.evidenceIndex[oldId];obj.evidenceCompacted=Number(obj.evidenceCompacted||0)+Math.max(0,evKeys.length-256);
    }else if(op==='resolve-blocker'){
     if(!str(change.blocker)||!change.evidence||change.evidence.verified!==true||!str(String(change.evidence.id||''))||!(obj.blockers||[]).includes(change.blocker)){why='unverified-blocker-clearance';break;}obj.blockers=(obj.blockers||[]).filter(v=>v!==change.blocker);
    }else if(op==='complete'){
     if(!change.evidence||change.evidence.verified!==true||!str(String(change.evidence.id||''))||obj.progressUnits<d.target||(obj.blockers||[]).length){why='project-not-ready';break;}obj.status='completed';obj.completedTick=tick;
    }else{why='invalid-project-operation';break;}
   }else if(d.kind==='tracker'){
    if(op!=='set'||!str(change.field)||!has(d.fields,change.field)||!validField(d,change.field,change.value)){why='invalid-tracker-field';break;}obj.values[change.field]=change.value;
   }else{why='unsupported-domain';break;}
  }
  if(why){fail(id,why);continue;}
  for(const [key,{d,value}] of scratch){value.revision=Number(value.revision||0)+1;if(d.kind==='inventory')X.physical.batches[key]=value;else if(d.kind==='bank')R.economy[key]=value;else if(d.kind==='research')R.projects[key]=value;else if(d.kind==='meter')R.accumulators[key]=value;else R.trackers[key]=value;}
  last[adapter]=seq;seen[id]=tick;L.push({id,tick,at:now,status:'committed',adapter,seq,actor,receipt:String(job.receipt).slice(0,100),changed:changes.length,refs:changes.map(c=>c.id)});
  X.events.push({id:'e'+(X.eventSeq=Number(X.eventSeq||0)+1),tick,at:now,system:'sharedCoord',kind:'transaction',entityId:changes[0].id,actor,transactionId:id,salience:.45});
 }
 const max=Math.min(500,Math.max(20,Number(C.maxHistory)||120));while(L.length>max)L.shift();const ks=Object.keys(seen);if(ks.length>max*3)for(const k of ks.sort((a,b)=>seen[a]-seen[b]).slice(0,ks.length-max*3))delete seen[k];
 }
}
}

lcx_group_project.script:
// Projection only. m.groups is authoritative for group membership; X.entities remains authoritative for actor identity.
const X=storage.LCX,m=X?.groups,C=X?.config?.groupContinuity;
if(!X||!m||C?.enabled===false||X.config.modules.groupContinuity===false){skip=true;}else{
const issues=[],rev={},caps={};const limit=Math.max(1,Number(C.maxGroups||256));
for(const [id,g] of Object.entries(m.groups).slice(0,limit)){if(!g)continue;let identified=0,anonymous=0;for(const [eid,edgeId] of Object.entries(g.members||{})){const e=m.edges?.[edgeId];if(!e||e.active!==true||e.entityId!==eid||e.groupId!==id)issues.push('edge-mismatch:'+id+':'+eid);else{identified++;(rev[eid]??(rev[eid]=[])).push(id);}}for(const c of Object.values(g.cohorts||{})){const q=Number(c.remaining);if(!Number.isSafeInteger(q)||q<0)issues.push('bad-cohort:'+id+':'+c.id);else anonymous+=q;}
caps[id]={id,name:String(g.name||id),kind:String(g.kind||'team'),status:String(g.status||'active'),count:identified+anonymous,named:identified,anonymous,memberIds:Object.keys(g.members||{}).slice(0,6),orders:(g.orders||[]).slice(-3).map(k=>({id:k,status:m.orders?.[k]?.status||'unknown'})),location:g.baseLocation??null,revision:g.revision||0};}
for(const [id,groups] of Object.entries(rev)){let ds=new Set();for(const gid of groups){const d=m.groups?.[gid]?.exclusiveDomain;if(d){if(ds.has(d))issues.push('exclusive-membership:'+id+':'+d);ds.add(d);}}}
m.reverse=rev;m.capsules=caps;const all=issues.concat(m.diagnostics||[]);m.validation={tick:Number(check({type:'game-tick'})||0),groups:Object.keys(caps).length,issueCount:all.length,issues:all.slice(0,32)};
}


// Promote LC-only group individuals into LCX actor continuity, but never create native Voyage NPCs.
{
const X=storage.LCX,m=X?.groups;if(X&&m){const max=Math.max(1,Math.min(32,Number(X.config?.groupContinuity?.maxActorAdmissionsPerTurn||8))),ids=Object.values(m.entities||{}).filter(q=>q?.kind==='lc-only'&&q.hostSyncStatus==='not-native'&&!X.entities?.[q.id]).slice(0,max);
for(const q of ids){const gs=(m.reverse?.[q.id]||[]).map(id=>m.groups[id]).filter(Boolean),g=gs[0];X.entities[q.id]={id:q.id,kind:'npc',source:'lcx-group-promotion',native:false,significance:'incidental',present:false,scenePresence:false,role:'group member',groupOrigin:{groupId:g?.id||null,cohortId:q.fromCohort||null},evidence:[],knowledge:{},memory:[],psyche:{}};}
const done=m.projectedAuditKeys??(m.projectedAuditKeys={});for(const a of (m.audit||[]).slice(-48)){if(a?.status!=='applied'||!a.key||done[a.key])continue;done[a.key]=1;X.events.push({id:'e'+(X.eventSeq=Number(X.eventSeq||0)+1),tick:Number(check({type:'game-tick'})||0),at:X.clock?.absoluteMinutes,system:'group',kind:a.type,groupId:a.groupId||null,entityId:a.entityId||null,source:a.source||'host',salience:['join','leave','transfer','promote','disband'].includes(a.type)?.4:.2,summary:'Confirmed group ledger change: '+String(a.type||'change')+'; no implied NPC consent or successful order.'});}
if(Object.keys(done).length>512)for(const k of Object.keys(done).slice(0,Object.keys(done).length-512))delete done[k];
}}

lcx_shared_context.script:
// Read current-turn effectiveAction AFTER LCX command router and session projection.
const X=storage.LCX,S=X?.sharedCoord,R=X?.registries;
if(!X||!S||X.command?.only||X.config?.modules?.sharedCoord===false){skip=true;}else{
const action=String(X.command?.effectiveAction||'').toLowerCase(),players=Array.isArray(X.session?.players)?X.session.players.map(String):[],rows=[];
if(action){for(const d of Object.values(S.defs||{})){
const label=String(d?.label||''),id=String(d?.id||'');if(!id||!(action.includes(label.toLowerCase())||action.includes(id.toLowerCase())))continue;
const permitted=d.visibility==='public'||d.visibility==='members'&&players.length>0&&(d.scope==='party'||d.scope==='group'&&players.every(p=>X.groups?.edges?.[d.owner+'|'+p]?.active===true));if(!permitted)continue;
let line='';if(d.kind==='bank')line='balances='+JSON.stringify(R.economy?.[id]?.balances||{});
else if(d.kind==='research'){const p=R.projects?.[id];line='effort='+Number(p?.progressUnits||0)+'/'+d.target+' status='+String(p?.status||'unknown')+' blockers='+JSON.stringify(p?.blockers||[]);}
else if(d.kind==='meter')line='value='+Number(R.accumulators?.[id]?.value||0);
else if(d.kind==='tracker')line='fields='+JSON.stringify(R.trackers?.[id]?.values||{});
