const X=storage.LCX,ctx=X?.context,tick=Number(check({type:'game-tick'})||0);
if(!X||X.command?.only||!ctx||ctx.tick!==tick){skip=true;}else{
const players=new Set((X.session?.players||[]).map(String)),out=[],reasons={};
for(const c of ctx.candidates||[]){if(!c||typeof c.id!=='string')continue;
 let why='';const aud=c.audience,vis=c.visibility;
 if(vis!=='public')why='unverified-visibility';
 else if(c.viewerId!==undefined||c.ownerPlayerId!==undefined||c.visibility==='player'||c.visibility==='private')why='player-specific';
 else if(Array.isArray(c.playerIds)&&c.playerIds.length)why='player-specific';
 else if(Array.isArray(aud)&&aud.length&&!aud.includes('public')&&!aud.includes('world')&&!aud.includes('all'))why='restricted-audience';
 else if(typeof aud==='string'&&aud&&!['public','world','all'].includes(aud))why='restricted-audience';
 // Do not infer that every NPC's knowledge, relationships or private psyche is party-public.
 else if(/^actor:[^:]+:(knowledge|relationships|threads|psyche)$/.test(c.id)&&players.size>1&&!c.evidencePublic)why='npc-private';
 else if(/^deep:/.test(c.id)&&players.size>1&&!c.evidencePublic)why='npc-private';
 if(why){reasons[why]=(reasons[why]||0)+1;continue;}out.push(c);
