}

lcx_field_governor.script:
// LCX authoritative field governor: deterministic complete-capsule transport, no state mutations.
const X=storage.LCX,ctx=X?.context,tick=Number(check({type:'game-tick'})||0);
if(!X||X.command?.only||!ctx||ctx.tick!==tick){skip=true;}else{
const F=X.config.fieldGovernor||{},cap=Math.max(0,Math.min(9,Math.floor(Number(F.maxPackets??9)))),limit=Math.max(64,Math.min(900,Math.floor(Number(F.maxPacketChars??900)))),budget=Math.min(Math.max(0,Math.floor(Number(X.config.limits?.maxContextChars??8100))),cap*limit),maxCandidates=Math.max(1,Math.min(4096,Math.floor(Number(F.maxCandidates??512)))),header0=String(F.header??'LCX TURN CONTEXT\n'),header= /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?:^|[^\uD800-\uDBFF])[\uDC00-\uDFFF]/.test(header0)?'LCX TURN CONTEXT\n':header0;
const malformed=s=>/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?:^|[^\uD800-\uDBFF])[\uDC00-\uDFFF]/.test(s);
const counts={},deferred=[],selected=[],manifest=[],packets=[],valid=[],priority=c=>Math.max(-9999,Math.min(9999,Number(c.priority)||0)),relevance=c=>{const act=String(X.command?.effectiveAction||'').toLowerCase();if(!act)return 0;return (c.entities||[]).some(id=>act.includes(String(id).toLowerCase()))?8:0;};
const defer=(id,reason)=>{counts[reason]=(counts[reason]||0)+1;if(deferred.length<48)deferred.push({id:reason==='viewer-private'?'[private]':String(id).slice(0,96),reason});};
const raw=Array.isArray(ctx.candidates)?ctx.candidates:[];
for(const c of raw){if(!c||typeof c.id!=='string'||typeof c.text!=='string'||!c.text)continue;
 const domain=String(c.sourceDomain||c.id.split(':')[0]);
 // Party-narrator stream has no verified per-viewer privacy boundary; unknown audience fails closed.
 const visibility=c.visibility;
 if(visibility!=='public'){defer(c.id,'viewer-private');continue;}
 if(c.viewerId!==undefined||c.ownerPlayerId!==undefined||c.playerIds&&c.playerIds.length||c.visibility==='private'){defer(c.id,'viewer-private');continue;}
 const text='['+c.id+'] '+c.text;if(malformed(text)){defer(c.id,'invalid-unicode');continue;}
 if(text.length>limit-header.length){defer(c.id,'oversize-atomic');if(c.critical===true||c.tier==='mandatory'||c.id==='core'||c.id==='authority-conflicts')counts['critical-oversize']=(counts['critical-oversize']||0)+1;continue;}
 const tier=c.tier==='mandatory'||c.critical===true||c.id==='core'||c.id==='authority-conflicts'?0:c.tier==='protected'||priority(c)>=80?1:priority(c)>=60?2:3;
 valid.push({c,text,tier,score:priority(c)+relevance(c)});
}
valid.sort((a,b)=>a.tier-b.tier||b.score-a.score||String(a.c.id).localeCompare(String(b.c.id)));
