let packet='',ids=[],entries=[],used=0;const flush=()=>{if(!ids.length)return;const str=header+packet;packets.push(str);manifest.push({index:packets.length-1,ids:ids.slice(),sources:entries.slice(),chars:str.length});used+=str.length;packet='';ids=[];entries=[];};
let criticalOverflow=!!counts['critical-oversize'];
for(const q of valid){const append=(ids.length?'\n':'')+q.text;
 if(header.length+packet.length+append.length>limit){flush();}
 const next=(ids.length?'\n':'')+q.text;
 if(packets.length>=cap||used+header.length+packet.length+next.length>budget){defer(q.c.id,'transport-budget');if(q.tier===0)criticalOverflow=true;continue;}
 // Final serialized-size check owns every byte of overhead, not c.chars metadata.
 packet+=next;ids.push(q.c.id);entries.push({id:q.c.id,sourceDomain:String(q.c.sourceDomain||q.c.id.split(':')[0]),sourceRef:String(q.c.sourceRef||q.c.id),revision:Number(q.c.sourceRevision??q.c.revision??0)||0});selected.push(q.c);
