if(criticalOverflow&&!packets.length&&cap>0&&budget>=header.length+72){const t=header+'LCX CONTEXT OVERFLOW: constraints not fully projected. Host rules still apply.';packets.push(t);manifest.push({index:0,ids:[],chars:t.length});}
