if(!good){M.status='blocked-migration-integrity';M.runtimeAudit.blocked=true;}
// This is a diagnostic projection, never a source of canonical quest or financial results.
// No story effects, no conversion, no OOC command interpretation.
skip=true;
}

lcx_institutional_life_context.script:
/* LCX bounded institutional context adapter: party-visible, relevant, and non-authoritative. */
const X=storage.LCX,I=X?.institutionalLife,C=X?.config?.institutionalLife;
if(!X||!I||!C||X.config?.modules?.institutionalLife===false||C.enabled===false||!X.context||X.command?.only){skip=true;}
else {
 const action=String(X.command?.effectiveAction||'').toLowerCase(),scene=new Set([...(X.scene?.active||[]),...(X.scene?.ambient||[])]),players=(X.session?.players||[]).map(String),pCount=players.length;
 const hot=/\b(?:work|job|employ|hire|contract|school|acad|enroll|graduate|license|permit|lease|rent|housing|tenant|business|office|credential|certif|sanction|suspend|appeal|deny|denied|renew|duty|shift|appointment|institution|application|offer|status)\w*/i.test(action);
 const scored=[];
 for(const r of Object.values(I.records||{})){
  if(!r||r.retired||r.sourceHealthy!==true||r.visibility!=='public'||!r.status)continue;
  const HP=X.config?.hostProjection?.institutionBindings||{},standalone=C.bindings?.[r.bindingId],host=HP[r.bindingId];
  if(standalone&&host?.institutionalLife)continue;
  const b=standalone||host?.institutionalLife;if(!b||b.enabled===false||b.visibility!=='public')continue;
  const who=b.ownerEntity??host?.ownerEntity;
  if((who==='primary-player'?(pCount===1?players[0]:null):String(who||''))!==String(r.entityId))continue;
  const source=b.statusSource||b.source||host?.source;
  if(!source||source.key!==r.statusSourceKey)continue;
  let live=storage,valid=true;
  for(const key of String(source.key).split('.')){if(!live||typeof live!=='object'||!Object.prototype.hasOwnProperty.call(live,key)){valid=false;break;}live=live[key];}
  if(!valid||live==null||typeof live==='object'||typeof live==='function'||typeof live!==typeof r.statusRaw||live!==r.statusRaw)continue;
  const status=source.type==='storageBoolean'?(live?String(b.trueStatus||'active'):String(b.falseStatus||'not-active')):String(b.statusMap&&Object.prototype.hasOwnProperty.call(b.statusMap,String(live).trim())?b.statusMap[String(live).trim()]:String(live).trim()).toLowerCase();
  if(status!==r.status)continue;
  // Party context is shared. Private player-specific records are never emitted in multiplayer.
  if(pCount>1&&(players.includes(String(r.entityId))||X.entities?.[r.entityId]?.kind==='player'||X.creationCanon?.players?.[r.entityId]))continue;
  const name=String(r.roleLabel||'').toLowerCase(),org=String(r.organizationId||'').toLowerCase(),id=String(r.entityId||'').toLowerCase();
  const relevant=action&&(hot||name&&action.includes(name)||org&&action.includes(org)||id&&action.includes(id));
  if(!relevant&&!scene.has(String(r.entityId)))continue;
  const score=(relevant?20:0)+(scene.has(String(r.entityId))?8:0)+(action.includes(org)&&org?10:0)+Math.max(0,4-(Number(X.lastTick||0)-Number(r.lastChangedTick||0)));
  scored.push({r,score});
 }
 scored.sort((a,b)=>b.score-a.score||String(a.r.id).localeCompare(String(b.r.id)));
 const max=Math.max(0,Math.min(4,Number(C.maxContextRows??2)||0)),chars=Math.max(0,Math.min(1800,Number(C.maxContextChars??750)||0));let used=0,n=0;
 for(const {r} of scored){if(n>=max||used>=chars)break;
  const details=['INSTITUTIONAL STATUS (host-observed; no automatic rights or outcomes):',r.roleLabel+' at '+(r.organizationId||'unspecified institution'), 'entity='+r.entityId,'status='+r.status,'authority=host'];
  if(r.effectiveEvidence?.value!==undefined)details.push('effective='+String(r.effectiveEvidence.value));
  if(r.expirationEvidence?.value!==undefined)details.push('expires='+String(r.expirationEvidence.value));
  if(r.expirationDue)details.push('expiration-date-passed; no inferred revocation');
  if(r.appealEvidence?.value&&r.appealEvidence.value!=='none')details.push('appeal='+r.appealEvidence.value);
  if(r.renewalEvidence?.value&&r.renewalEvidence.value!=='none')details.push('renewal='+r.renewalEvidence.value);
  details.push('schedule≠attendance, offered≠accepted, claims≠host decision');
  const value=details.join(' ');if(value.length>Math.min(500,chars-used))continue;
  X.context.candidates.push({id:'institutional:'+r.bindingId,priority:69,text:value,chars:value.length,entities:[r.entityId],visibility:'public',sourceDomain:'institutionalLife',sourceRef:r.id,sourceRevision:Number(r.revision||0)});
  used+=value.length;n++;
 }
 if(!n)skip=true;
}

lcx_npc_competence_interface.script:
const X=storage.LCX;if(!X||!X.command?.raw){skip=true;}else{const cmd=String((X.command.commands||[])[0]||X.command.raw),msg=[];const out=s=>msg.push(String(s));if(/^:lc\s+npc(?:\s|$)/i.test(cmd)){const bits=cmd.split(/\s+/),mode=String(bits[2]||'help').toLowerCase(),id=String(bits[3]||''),N=X.npcChecks||{},K=X.config?.competency?.npcChecks||{};
if(mode==='help')out('LCX NPC competence: :lc npc skills <npcId> | :lc npc last [attemptId] | :lc npc help. NPC action checks require an LCX host-committed action event; the interface does not create NPC actions.');
else if(mode==='skills'){if(!id)out('Usage: :lc npc skills <npcId>');else if(X.session?.players?.length>1&&X.entities?.[id]?.kind==='player')out('Player-private competency unavailable in shared diagnostics.');else{const rs=Object.values(X.registries?.competencies||{}).filter(q=>q?.entityId===id&&q?.assessment?.rating100!==undefined).slice(0,24).map(q=>({skill:q.assessment.sourceSkillId||q.name,rating100:q.assessment.rating100,level:q.level})),ability=N.actorConstraints?.[id]?.abilities||{};out(rs.length||Object.keys(ability).length?'LCX NPC '+id+': '+JSON.stringify({skills:rs,abilities:ability}).slice(0,1600):'No configured NPC-specific ratings for '+id+'.');}}
else if(mode==='last'){const result=id?N.results?.[id]:N.results?.[N.history?.[N.history.length-1]?.attemptId];out(result?'LCX NPC CHECK '+JSON.stringify(result).slice(0,1500):'No resolved NPC check for this attempt ID.');}
else if(mode==='queue')out('NPC queue cannot authorize an action. A host trigger must write an npc-action-committed event and matching request with commitmentEventId; no roll on an intent or OOC command.');
else out('Unknown LCX NPC command. Use :lc npc help.');}
if(msg.length)effects.push({type:'story',instruction:'OUT-OF-WORLD LCX INTERFACE. Do not advance fiction. '+msg.join('\n')});else skip=true;}
